const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / 100;
}

function componentsBasePremium(components: Item[]): number {
  const countsByType = new Map<string, number>();
  components.forEach((item) => countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1));
  return [...countsByType.values()].reduce((sum, count) => sum + componentGroupBasePremium(count), 0);
}

function componentGroupBasePremium(count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

export function premiumFor(items: Item[]): number {
  const mainItems = items.filter((item) => item.type in BASE_PREMIUMS);
  const components = items.filter((item) => !(item.type in BASE_PREMIUMS));
  const base =
    mainItems.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0) + componentsBasePremium(components);
  return Math.ceil(base + percentOf(base, FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
}
